const normalizeTitle = (value: string) => value.toLowerCase().replace(/[^a-z0-9]+/g, "");

const SAMPLE_BY_TITLE = new Map(sampleSteamhProjects.map((project) => [normalizeTitle(project.title), project] as const));

const mergeLinks = (primary: SteamhProjectLink[], fallback: SteamhProjectLink[]) => {
  const merged: SteamhProjectLink[] = [];
  const seen = new Set<string>();
  for (const link of [...primary, ...fallback]) {
    const url = typeof link.url === "string" ? link.url.trim() : "";
    if (!url || seen.has(url)) continue;
    seen.add(url);
    merged.push({ url, label: link.label?.trim() || undefined });
  }
  return merged;
};

const shouldFallbackText = (value: string, minimumLength: number) => value.trim().length < minimumLength;

export const enrichSteamhProjectWithSampleDetails = (project: SteamhProject): SteamhProject => {
  const sample = SAMPLE_BY_TITLE.get(normalizeTitle(project.title));
  if (!sample) return project;

  const description = shouldFallbackText(project.description, 120) ? sample.description : project.description;
  const challenge = shouldFallbackText(project.challenge, 24) ? sample.challenge : project.challenge;
  const solution = shouldFallbackText(project.solution, 24) ? sample.solution : project.solution;

  return {
    ...project,
    grade: project.grade.trim() || sample.grade,
    subject: project.subject.trim() || sample.subject,
    summary: shouldFallbackText(project.summary, 50) ? sample.summary : project.summary,
    description,
    challenge,
    solution,
    toolsUsed: project.toolsUsed.length > 0 ? project.toolsUsed : sample.toolsUsed,
    tags: project.tags.length > 0 ? project.tags : sample.tags,
    imageUrls: project.imageUrls.length > 0 ? project.imageUrls : sample.imageUrls,
    videoUrls: project.videoUrls.length > 0 ? project.videoUrls : sample.videoUrls,
    attachmentUrls: project.attachmentUrls.length > 0 ? project.attachmentUrls : sample.attachmentUrls,
    externalLinks: mergeLinks(project.externalLinks, sample.externalLinks),
  };
};

